import os,re,json
from collections import deque, Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(g):
    R=len(g); C=len(g[0])
    g=[row[:] for row in g]
    def bfs(v,i,j):
        q=deque([(i,j)]); seen=set([(i,j)]); cc=[]
        while q:
            a,b=q.popleft(); cc.append((a,b))
            for da in(-1,0,1):
                for db in(-1,0,1):
                    x,y=a+da,b+db
                    if 0<=x<R and 0<=y<C and (x,y) not in seen and g[x][y]==v:
                        seen.add((x,y)); q.append((x,y))
        return cc
    seen_all=[[False]*C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            v=g[i][j]
            if v!=g[0][0]: continue
    # collect non-background components: treat all non-most-common-cell-value
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    for i in range(R):
        for j in range(C):
            v=g[i][j]
            if v!=bg and not seen_all[i][j]:
                q=deque([(i,j)]); seen_all[i][j]=True; cc=[]
                while q:
                    a,b=q.popleft(); cc.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<R and 0<=y<C and not seen_all[x][y] and g[x][y]==v:
                                seen_all[x][y]=True; q.append((x,y))
                rs=[a for a,b in cc]; cl=[b for a,b in cc]
                r0,c0,r1,c1=min(rs),min(cl),max(rs),max(cl)
                h=r1-r0+1; w=c1-c0+1
                fill = 7 if (h%2==1 and w%2==1) else 2
                for i2 in range(r0,r1+1):
                    for j2 in range(c0,c1+1):
                        if g[i2][j2]!=v:
                            g[i2][j2]=fill
    return g
