def components(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    r,c=st.pop(); cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(r+dr,c+dc)
                        if 0<=n[0]<H and 0<=n[1]<W and not seen[n[0]][n[1]] and g[n[0]][n[1]]==g[i][j]:
                            seen[n[0]][n[1]]=True; st.append(n)
                comps.append(cells)
    return comps

def solve(g):
    gi=g; H,W=len(gi),len(gi[0]); bg=gi[0][0]; out=[row[:] for row in gi]
